// Ödeme verilerini doğrula
const body = $input.item.json.body;

const requiredFields = ['user_id', 'plan_type', 'amount', 'card_number', 'card_expiry', 'card_cvv'];
const missingFields = requiredFields.filter(field => !body[field]);

if (missingFields.length > 0) {
  throw new Error(`Eksik alanlar: ${missingFields.join(', ')}`);
}

// Plan kontrolü
const validPlans = ['monthly', 'semi_annual', 'annual'];
if (!validPlans.includes(body.plan_type)) {
  throw new Error('Geçersiz plan tipi');
}

// Tutar kontrolü
const planPrices = {
  monthly: 250,
  semi_annual: 600,
  annual: 1000
};

if (body.amount !== planPrices[body.plan_type]) {
  throw new Error('Geçersiz tutar');
}

return { json: body };

// Ödeme işlemi simülasyonu
// Gerçek uygulamada burası ödeme gateway'i ile entegre edilecek

const data = $input.item.json;

// Kart numarası doğrulama (Luhn algoritması basit versiyonu)
const cardNumber = data.card_number.replace(/\s/g, '');

if (cardNumber.length < 15 || cardNumber.length > 16) {
  throw new Error('Geçersiz kart numarası');
}

// Son kullanma tarihi kontrolü
const [expMonth, expYear] = data.card_expiry.split('/');
const expiryDate = new Date(2000 + parseInt(expYear), parseInt(expMonth) - 1);
const now = new Date();

if (expiryDate < now) {
  throw new Error('Kartın süresi dolmuş');
}

// CVV kontrolü
if (data.card_cvv.length !== 3 && data.card_cvv.length !== 4) {
  throw new Error('Geçersiz CVV');
}

// Simüle edilmiş ödeme işlemi (2 saniye bekleme)
await new Promise(resolve => setTimeout(resolve, 2000));

// Transaction ID oluştur
const transactionId = `TXN${Date.now()}${Math.floor(Math.random() * 1000)}`;

// Başarılı ödeme
return {
  json: {
    ...data,
    transaction_id: transactionId,
    payment_status: 'completed',
    payment_date: new Date().toISOString(),
    masked_card: `****-****-****-${cardNumber.slice(-4)}`
  }
};

// Abonelik süresini hesapla
const data = $input.item.json;
const startDate = new Date();
let endDate = new Date();

const planDurations = {
  monthly: 1,
  semi_annual: 6,
  annual: 12
};

endDate.setMonth(endDate.getMonth() + planDurations[data.plan_type]);

return {
  json: {
    user_id: data.user_id,
    plan_type: data.plan_type,
    status: 'active',
    start_date: startDate.toISOString(),
    end_date: endDate.toISOString(),
    free_questions_used: 0,
    is_trial: false,
    auto_renew: true,
    payment_id: data.id // Kaydedilen payment'ın ID'si
  }
};

// Başarılı yanıt oluştur
const subscription = $input.item.json;
const payment = $node['Ödeme Kaydı Oluştur'].json;

return {
  json: {
    success: true,
    message: 'Ödeme başarıyla tamamlandı ve aboneliğiniz aktif edildi',
    subscription: {
      id: subscription.id,
      plan_type: subscription.plan_type,
      status: subscription.status,
      start_date: subscription.start_date,
      end_date: subscription.end_date
    },
    payment: {
      transaction_id: payment.transaction_id,
      amount: payment.amount,
      currency: payment.currency,
      date: payment.payment_date
    },
    timestamp: new Date().toISOString()
  }
};

// Hata yakalama
const error = $input.item.json.error || $input.item.json;

return {
  json: {
    success: false,
    error: error.message || 'Ödeme işlemi başarısız',
    error_code: error.code || 'PAYMENT_ERROR',
    timestamp: new Date().toISOString()
  }
};
